Q: linq expression for ExecuteUpdateAsync A: <p>Try the following extensions. I have also corrected method signature:</p>
<pre class="lang-cs prettyprint-override"><code>var affected = anyQuery.ExecuteUpdate(FieldName, FieldValue);

var affected = await anyQuery.ExecuteUpdateAsync(FieldName, FieldValue, cancellationToken);
</code></pre>
<p>Updated version also supports multiple fields for update:</p>
<pre class="lang-cs prettyprint-override"><code>var affected = anyQuery.ExecuteUpdate(new Dictionary&lt;string, object?&gt; 
{ 
    { FieldName1, FieldValue2 }, 
    { FieldName2, FieldValue2 } 
});
</code></pre>
<h3>EF Core 10+ implementation:</h3>
<pre class="lang-cs prettyprint-override"><code>public static class DynamicRelationalExtensions
{
    static readonly MethodInfo UpdateMethodInfo = typeof(DynamicRelationalExtensions)
        .GetMethods(BindingFlags.NonPublic | BindingFlags.Static)
        .Single(m =&gt; m.Name == nameof(ExecuteUpdateInternal));

    static readonly MethodInfo UpdateAsyncMethodInfo = typeof(DynamicRelationalExtensions)
        .GetMethods(BindingFlags.NonPublic | BindingFlags.Static)
        .Single(m =&gt; m.Name == nameof(ExecuteUpdateInternalAsync));

    public static int ExecuteUpdate(this IQueryable query, string fieldName, object? fieldValue) 
        =&gt; ExecuteUpdate(query, new Dictionary&lt;string, object?&gt; { { fieldName, fieldValue } });

    public static Task&lt;int&gt; ExecuteUpdateAsync(this IQueryable query, string fieldName, object? fieldValue, CancellationToken cancellationToken = default) 
        =&gt; ExecuteUpdateAsync(query, new Dictionary&lt;string, object?&gt; { { fieldName, fieldValue } }, cancellationToken);

    public static int ExecuteUpdate(this IQueryable query, IReadOnlyDictionary&lt;string, object?&gt; fieldValues)
    {
        var updateMethod = UpdateMethodInfo.MakeGenericMethod(query.ElementType);

        return (int)updateMethod.Invoke(null,
        [
            query,
            fieldValues
        ])!;
    }

    public static Task&lt;int&gt; ExecuteUpdateAsync(this IQueryable query, IReadOnlyDictionary&lt;string, object?&gt; fieldValues, CancellationToken cancellationToken = default)
    {
        var updateMethod = UpdateAsyncMethodInfo.MakeGenericMethod(query.ElementType);

        return (Task&lt;int&gt;)updateMethod.Invoke(null,
        [
            query,
            fieldValues,
            cancellationToken
        ])!;
    }

    static int ExecuteUpdateInternal&lt;TEntity&gt;(IQueryable&lt;TEntity&gt; query, IReadOnlyDictionary&lt;string, object?&gt; fieldValues)
        where TEntity : class
    {
        return query.ExecuteUpdate(b =&gt; BuildUpdateBody(b, fieldValues));
    }

    static Task&lt;int&gt; ExecuteUpdateInternalAsync&lt;TEntity&gt;(IQueryable&lt;TEntity&gt; query, IReadOnlyDictionary&lt;string, object?&gt; fieldValues, CancellationToken cancellationToken)
        where TEntity : class
    {
        return query.ExecuteUpdateAsync(b =&gt; BuildUpdateBody(b, fieldValues), cancellationToken);
    }

    static void BuildUpdateBody&lt;TEntity&gt;(UpdateSettersBuilder&lt;TEntity&gt; builder, IReadOnlyDictionary&lt;string, object?&gt; fieldValues)
    {
        var entityType = typeof(TEntity);
        var objParam = Expression.Parameter(entityType, &quot;e&quot;);

        foreach (var pair in fieldValues)
        {
            var propExpression = Expression.PropertyOrField(objParam, pair.Key);
            var valueExpression = ValueForType(propExpression.Type, pair.Value);
#pragma warning disable EF1001
            builder.SetProperty(Expression.Lambda(propExpression, objParam), valueExpression);
#pragma warning restore EF1001
        }
    }

    static Expression ValueForType(Type desiredType, object? value)
    {
        if (value == null)
        {
            return Expression.Default(desiredType);
        }

        if (value.GetType() != desiredType)
        {
            return Expression.Convert(Expression.Constant(value), desiredType);
        }

        return Expression.Constant(value);
    }
}
</code></pre>
<h3>EF Core 7, 8, 9 implementation:</h3>
<pre class="lang-cs prettyprint-override"><code>public static class DynamicRelationalExtensions
{
    static MethodInfo UpdateMethodInfo =
        typeof(RelationalQueryableExtensions).GetMethod(nameof(RelationalQueryableExtensions.ExecuteUpdate));

    static MethodInfo UpdateAsyncMethodInfo =
        typeof(RelationalQueryableExtensions).GetMethod(nameof(RelationalQueryableExtensions.ExecuteUpdateAsync));

    public static int ExecuteUpdate(this IQueryable query, string fieldName, object? fieldValue)
    {
        var updateBody = BuildUpdateBody(query.ElementType,
            new Dictionary&lt;string, object?&gt; { { fieldName, fieldValue } });

        return (int)UpdateMethodInfo.MakeGenericMethod(query.ElementType).Invoke(null, new object?[] { query, updateBody });
    }

    public static Task&lt;int&gt; ExecuteUpdateAsync(this IQueryable query, string fieldName, object? fieldValue, CancellationToken cancellationToken = default)
    {
        var updateBody = BuildUpdateBody(query.ElementType,
            new Dictionary&lt;string, object?&gt; { { fieldName, fieldValue } });

        return (Task&lt;int&gt;)UpdateAsyncMethodInfo.MakeGenericMethod(query.ElementType).Invoke(null, new object?[] { query, updateBody, cancellationToken })!;
    }

    public static int ExecuteUpdate(this IQueryable query, IReadOnlyDictionary&lt;string, object?&gt; fieldValues)
    {
        var updateBody = BuildUpdateBody(query.ElementType, fieldValues);

        return (int)UpdateMethodInfo.MakeGenericMethod(query.ElementType).Invoke(null, new object?[] { query, updateBody });
    }

    public static Task&lt;int&gt; ExecuteUpdateAsync(this IQueryable query, IReadOnlyDictionary&lt;string, object?&gt; fieldValues, CancellationToken cancellationToken = default)
    {
        var updateBody = BuildUpdateBody(query.ElementType, fieldValues);

        return (Task&lt;int&gt;)UpdateAsyncMethodInfo.MakeGenericMethod(query.ElementType).Invoke(null, new object?[] { query, updateBody, cancellationToken })!;
    }

    static LambdaExpression BuildUpdateBody(Type entityType, IReadOnlyDictionary&lt;string, object?&gt; fieldValues)
    {
        var setParam = Expression.Parameter(typeof(SetPropertyCalls&lt;&gt;).MakeGenericType(entityType), &quot;s&quot;);
        var objParam = Expression.Parameter(entityType, &quot;e&quot;);

        Expression setBody = setParam;

        foreach (var pair in fieldValues)
        {
            var propExpression = Expression.PropertyOrField(objParam, pair.Key);
            var valueExpression = ValueForType(propExpression.Type, pair.Value);

            // s.SetProperty(e =&gt; e.SomeField, value)
            setBody = Expression.Call(setBody, nameof(SetPropertyCalls&lt;object&gt;.SetProperty),
                new[] { propExpression.Type }, Expression.Lambda(propExpression, objParam), valueExpression);

        }

        // s =&gt; s.SetProperty(e =&gt; e.SomeField, value)
        var updateBody = Expression.Lambda(setBody, setParam);

        return updateBody;
    }

    static Expression ValueForType(Type desiredType, object? value)
    {
        if (value == null)
        {
            return Expression.Default(desiredType);
        }

        if (value.GetType() != desiredType)
        {
            return Expression.Convert(Expression.Constant(value), desiredType);
        }

        return Expression.Constant(value);
    }
}
</code></pre>

Q: How to preview email templates of Woocommerce A: <p>After 12 years, I will post significant update on this, if it will be needed for somebody.</p>
<pre class="lang-php prettyprint-override"><code>/**
 * Open a preview e-mail.
 * https://example.org/wp-admin/admin-ajax.php?action=previewemail&amp;file=emails/customer-processing-order.php&amp;order=180
 *
 * @return null
 */
function preview_email() {
    global $order;

    // Check user capabilities
    if ( ! current_user_can( 'manage_woocommerce' ) ) {
        wp_die( 'Unauthorized access', 403 );
    }

    // Validate and sanitize inputs
    if ( ! isset( $_GET['file'] ) || ! isset( $_GET['order'] ) ) {
        wp_die( 'Missing required parameters' );
    }

    $filename = sanitize_text_field( $_GET['file'] );
    $orderId  = absint( $_GET['order'] );

    // Validate order ID
    if ( $orderId &lt;= 0 ) {
        wp_die( 'Invalid order ID' );
    }

    // Validate order exists
    $order = wc_get_order( $orderId );
    if ( ! $order ) {
        wp_die( 'Order not found: ' . $orderId );
    }

    // Validate file path to prevent directory traversal
    $allowed_path = WC()-&gt;plugin_path() . '/templates/';
    $file_path = $allowed_path . $filename;

    if ( ! file_exists( $file_path ) || strpos( realpath( $file_path ), realpath( $allowed_path ) ) !== 0 ) {
        wp_die( 'Invalid file path' );
    }

    // Set up required variables for email templates
    $email_heading = 'Email Preview';
    $sent_to_admin = false;
    $plain_text = false;
    $additional_content = '';

    // Get the actual email class for proper rendering
    $mailer = WC()-&gt;mailer();
    $emails = $mailer-&gt;get_emails();
    $email = $emails['WC_Email_Customer_Processing_Order'] ?? current( $emails );

    // Capture the email template output
    ob_start();
    include $file_path;
    $content = ob_get_clean();

    // Apply inline styles if email object has the method
    if ( method_exists( $email, 'style_inline' ) ) {
        echo $email-&gt;style_inline( $content );
    } else {
        echo $content;
    }

    exit;
}

add_action( 'wp_ajax_previewemail', 'preview_email' );
</code></pre>
